"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type { User } from "@/lib/api/user";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { Checkbox } from "@/components/ui/checkbox";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { Badge } from "@/components/ui/badge";

import { Users, Search, Pencil, Trash2 } from "lucide-react";

import {
  ArrowLeft,
  User,
  Mail,
  Shield,
  Lock,
  Eye,
  EyeOff,
  Save,
  Loader2,
  CheckCircle2,
} from "lucide-react";

import { useToast } from "@/hooks/use-toast";

import { createUser, deleteUser, getUsers } from "@/lib/api/user";

interface CreateUserForm {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  status: string;
}

export default function CreateUserPage() {
  const router = useRouter();
  const { toast } = useToast();

  const [loading, setLoading] = useState(false);

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [errors, setErrors] = useState<
    Partial<Record<keyof CreateUserForm, string>>
  >({});

  const [search, setSearch] = useState("");

  const [users, setUsers] = useState<User[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(false);
  const [deletingId, setDeletingId] = useState("");

  const filteredUsers = users.filter(
    (user: any) =>
      user.name.toLowerCase().includes(search.toLowerCase()) ||
      user.email.toLowerCase().includes(search.toLowerCase()),
  );

  const [formData, setFormData] = useState<CreateUserForm>({
    name: "",
    email: "",
    password: "",
    confirmPassword: "",
    status: "ACTIVE",
  });

  //---------------------------------------------------
  // Handle Input Change
  //---------------------------------------------------

  const handleInputChange = (
    field: keyof CreateUserForm,
    value: string | boolean,
  ) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }));

    if (errors[field]) {
      setErrors((prev) => ({
        ...prev,
        [field]: "",
      }));
    }
  };

  //---------------------------------------------------
  // Email Validation
  //---------------------------------------------------

  const validateEmail = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  //---------------------------------------------------
  // Form Validation
  //---------------------------------------------------

  const validateForm = () => {
    const newErrors: Partial<Record<keyof CreateUserForm, string>> = {};

    if (!formData.name.trim()) {
      newErrors.name = "Name is required";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!validateEmail(formData.email)) {
      newErrors.email = "Invalid email";
    }

    if (!formData.password) {
      newErrors.password = "Password is required";
    } else if (formData.password.length < 8) {
      newErrors.password = "Password must be at least 8 characters";
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword = "Confirm your password";
    }

    if (
      formData.password &&
      formData.confirmPassword &&
      formData.password !== formData.confirmPassword
    ) {
      newErrors.confirmPassword = "Passwords do not match";
    }

    setErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  };

  //---------------------------------------------------
  // Submit
  //---------------------------------------------------

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (!validateForm()) {
      toast({
        title: "Validation Error",
        description: "Please correct the highlighted fields.",
        variant: "destructive",
      });

      return;
    }

    setLoading(true);

    try {
      const response = await createUser({
        name: formData.name,
        email: formData.email,
        password: formData.password,
        role: formData.role,
        status: formData.status,
        forcePasswordReset: false,
      });

      if (!response.success) {
        throw new Error(response.error);
      }

      toast({
        title: "Success",
        description: "User created successfully.",
      });

      fetchUsers();

      setFormData({
        name: "",
        email: "",
        password: "",
        confirmPassword: "",
        role: "USER",
        status: "ACTIVE",
      });
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Unable to create user.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  //---------------------------------------------------
  // Page Starts Here
  //---------------------------------------------------

  const fetchUsers = async () => {
    setLoadingUsers(true);

    try {
      const response = await getUsers();

      if (response.success) {
        setUsers(response.users);
      }
    } finally {
      setLoadingUsers(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (id: string) => {
    try {
      setDeletingId(id);

      const response = await deleteUser(id);

      if (!response.success) {
        throw new Error(response.error);
      }

      toast({
        title: "Success",
        description: "User deleted successfully.",
      });

      fetchUsers();
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setDeletingId("");
    }
  };
  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">
        {/* Back Button */}

        <Link
          href="/"
          className="mb-6 inline-flex items-center gap-2 text-gray-400 hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Users
        </Link>

        {/* Form Starts */}

        <form onSubmit={handleSubmit}>
          {/* Header */}

          <div className="mb-8 flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <div className="flex items-center gap-3">
                <div className="rounded-xl bg-[#2563EB]/20 p-3">
                  <User className="h-7 w-7 text-[#4A9FD4]" />
                </div>

                <div>
                  <h1 className="text-3xl font-semibold text-[#4A9FD4]">
                    Create User
                  </h1>

                  <p className="mt-1 text-sm text-gray-400">
                    Add a new user and assign permissions for the Command
                    Center.
                  </p>
                </div>
              </div>
            </div>

            <div className="flex gap-3">
              <Button
                type="button"
                variant="outline"
                className="border-[#444] bg-transparent text-white hover:bg-[#333]"
                onClick={() => router.push("/users")}
              >
                Cancel
              </Button>

              <Button
                type="submit"
                disabled={loading}
                className="gap-2 bg-[#2563EB] text-white hover:bg-[#1D4ED8]"
              >
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <Save className="h-4 w-4" />
                    Create User
                  </>
                )}
              </Button>
            </div>
          </div>

          {/* ======================================================== */}
          {/* Summary Cards */}
          {/* ======================================================== */}

          <div className="mb-8 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-blue-500/20 p-3">
                  <User className="h-6 w-6 text-blue-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">Full Name</p>

                  <p className="truncate text-lg font-semibold text-white">
                    {formData.name || "--"}
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-green-500/20 p-3">
                  <Mail className="h-6 w-6 text-green-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">Email</p>

                  <p className="truncate text-lg font-semibold text-white">
                    {formData.email || "--"}
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-purple-500/20 p-3">
                  <Shield className="h-6 w-6 text-purple-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">Role</p>

                  <p className="text-lg font-semibold text-white">
                    {formData.role}
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-emerald-500/20 p-3">
                  <CheckCircle2 className="h-6 w-6 text-emerald-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">Status</p>

                  <p className="text-lg font-semibold text-white">
                    {formData.status}
                  </p>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* ======================================================== */}
          {/* Main Grid */}
          {/* ======================================================== */}

          <div className="grid gap-6 lg:grid-cols-2">
            {/* ==================================================== */}
            {/* User Information */}
            {/* ==================================================== */}

            <Card className="border-[#333] bg-[#222]">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-white">
                  <User className="h-5 w-5 text-[#4A9FD4]" />
                  User Information
                </CardTitle>
              </CardHeader>

              <CardContent className="space-y-6">
                {/* Name */}

                <div className="space-y-2">
                  <Label className="text-gray-300">Full Name</Label>

                  <Input
                    placeholder="Enter full name"
                    value={formData.name}
                    onChange={(e) => handleInputChange("name", e.target.value)}
                    className="border-[#333] bg-[#1B1B1B] text-white focus:border-[#2563EB]"
                  />

                  {errors.name && (
                    <p className="text-sm text-red-500">{errors.name}</p>
                  )}
                </div>

                {/* Email */}

                <div className="space-y-2">
                  <Label className="text-gray-300">Email Address</Label>

                  <Input
                    type="email"
                    placeholder="example@company.com"
                    value={formData.email}
                    onChange={(e) => handleInputChange("email", e.target.value)}
                    className="border-[#333] bg-[#1B1B1B] text-white focus:border-[#2563EB]"
                  />

                  {errors.email && (
                    <p className="text-sm text-red-500">{errors.email}</p>
                  )}
                </div>

                {/* Status */}

                <div className="space-y-2">
                  <Label className="text-gray-300">Status</Label>

                  <Select
                    value={formData.status}
                    onValueChange={(value) =>
                      handleInputChange("status", value)
                    }
                  >
                    <SelectTrigger className="border-[#333] bg-[#1B1B1B] text-white">
                      <SelectValue />
                    </SelectTrigger>

                    <SelectContent className="border-[#333] bg-[#222] text-white">
                      <SelectItem value="ACTIVE">Active</SelectItem>

                      <SelectItem value="INACTIVE">Inactive</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </CardContent>
            </Card>
            {/* ==================================================== */}
            {/* Security */}
            {/* ==================================================== */}

            <Card className="border-[#333] bg-[#222]">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-white">
                  <Lock className="h-5 w-5 text-[#4A9FD4]" />
                  Security
                </CardTitle>
              </CardHeader>

              <CardContent className="space-y-6">
                {/* Password */}

                <div className="space-y-2">
                  <Label className="text-gray-300">Password</Label>

                  <div className="relative">
                    <Input
                      type={showPassword ? "text" : "password"}
                      placeholder="Enter password"
                      value={formData.password}
                      onChange={(e) =>
                        handleInputChange("password", e.target.value)
                      }
                      className="border-[#333] bg-[#1B1B1B] pr-12 text-white focus:border-[#2563EB]"
                    />

                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 transition hover:text-white"
                    >
                      {showPassword ? (
                        <EyeOff className="h-5 w-5" />
                      ) : (
                        <Eye className="h-5 w-5" />
                      )}
                    </button>
                  </div>

                  {errors.password && (
                    <p className="text-sm text-red-500">{errors.password}</p>
                  )}
                </div>

                {/* Confirm Password */}

                <div className="space-y-2">
                  <Label className="text-gray-300">Confirm Password</Label>

                  <div className="relative">
                    <Input
                      type={showConfirmPassword ? "text" : "password"}
                      placeholder="Confirm password"
                      value={formData.confirmPassword}
                      onChange={(e) =>
                        handleInputChange("confirmPassword", e.target.value)
                      }
                      className="border-[#333] bg-[#1B1B1B] pr-12 text-white focus:border-[#2563EB]"
                    />

                    <button
                      type="button"
                      onClick={() =>
                        setShowConfirmPassword(!showConfirmPassword)
                      }
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 transition hover:text-white"
                    >
                      {showConfirmPassword ? (
                        <EyeOff className="h-5 w-5" />
                      ) : (
                        <Eye className="h-5 w-5" />
                      )}
                    </button>
                  </div>

                  {errors.confirmPassword && (
                    <p className="text-sm text-red-500">
                      {errors.confirmPassword}
                    </p>
                  )}
                </div>

                {/* Password Requirements */}

                <div className="rounded-lg border border-[#333] bg-[#1B1B1B] p-4">
                  <h4 className="mb-3 text-sm font-semibold text-[#4A9FD4]">
                    Password Requirements
                  </h4>

                  <div className="space-y-2 text-sm text-gray-400">
                    <div className="flex items-center gap-2">
                      <CheckCircle2
                        className={`h-4 w-4 ${
                          formData.password.length >= 8
                            ? "text-green-500"
                            : "text-gray-600"
                        }`}
                      />
                      Minimum 8 characters
                    </div>

                    <div className="flex items-center gap-2">
                      <CheckCircle2
                        className={`h-4 w-4 ${
                          /[A-Z]/.test(formData.password)
                            ? "text-green-500"
                            : "text-gray-600"
                        }`}
                      />
                      One uppercase letter
                    </div>

                    <div className="flex items-center gap-2">
                      <CheckCircle2
                        className={`h-4 w-4 ${
                          /[0-9]/.test(formData.password)
                            ? "text-green-500"
                            : "text-gray-600"
                        }`}
                      />
                      One number
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Bottom Buttons */}
        </form>

        <Card className="mt-10 border-[#333] bg-[#222]">
          <CardHeader className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex items-center gap-3">
              <div className="rounded-full bg-[#2563EB]/20 p-3">
                <Users className="h-6 w-6 text-[#4A9FD4]" />
              </div>

              <div>
                <CardTitle className="text-white">Existing Users</CardTitle>

                <p className="mt-1 text-sm text-gray-400">
                  Manage all registered users.
                </p>
              </div>
            </div>

            <div className="flex flex-col gap-3 sm:flex-row">
              <div className="relative">
                <Search className="absolute left-3 top-3 h-4 w-4 text-gray-500" />

                <Input
                  placeholder="Search users..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-72 border-[#333] bg-[#1B1B1B] pl-10 text-white"
                />
              </div>

              <Badge className="bg-[#2563EB] px-4 py-2">
                {users.length} Users
              </Badge>
            </div>
          </CardHeader>

          <CardContent>
            {loadingUsers ? (
              <div className="flex justify-center py-16">
                <Loader2 className="h-10 w-10 animate-spin text-[#2563EB]" />
              </div>
            ) : filteredUsers.length === 0 ? (
              <div className="py-16 text-center">
                <Users className="mx-auto mb-4 h-14 w-14 text-gray-500" />

                <h3 className="text-lg font-semibold text-white">
                  No Users Found
                </h3>

                <p className="mt-2 text-gray-400">
                  Create your first user to get started.
                </p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow className="border-[#333] hover:bg-transparent">
                      <TableHead className="text-gray-300">Name</TableHead>

                      <TableHead className="text-gray-300">Email</TableHead>

                      <TableHead className="text-gray-300">Role</TableHead>

                      <TableHead className="text-gray-300">Status</TableHead>

                      <TableHead className="text-gray-300">Created</TableHead>

                      <TableHead className="text-right text-gray-300">
                        Actions
                      </TableHead>
                    </TableRow>
                  </TableHeader>

                  <TableBody>
                    {filteredUsers.map((user: any) => (
                      <TableRow
                        key={user.id}
                        className="border-[#333] hover:bg-[#2A2A2A]"
                      >
                        <TableCell className="font-medium text-white">
                          {user.name}
                        </TableCell>

                        <TableCell className="text-gray-300">
                          {user.email}
                        </TableCell>

                        <TableCell>
                          <Badge
                            className={
                              user.role === "ADMIN"
                                ? "bg-blue-600"
                                : user.role === "OPERATOR"
                                  ? "bg-purple-600"
                                  : "bg-gray-600"
                            }
                          >
                            {user.role}
                          </Badge>
                        </TableCell>

                        <TableCell>
                          <Badge
                            className={
                              user.status ? "bg-green-600" : "bg-red-600"
                            }
                          >
                            {user.status ? "Active" : "Inactive"}
                          </Badge>
                        </TableCell>

                        <TableCell className="text-gray-300">
                          {new Date(user.createdAt).toLocaleDateString()}
                        </TableCell>

                        <TableCell>
                          <div className="flex justify-end gap-2">
                            <Button
                              size="icon"
                              variant="outline"
                              className="border-[#333] bg-transparent hover:bg-blue-600"
                            >
                              <Pencil className="h-4 w-4" />
                            </Button>

                            <AlertDialog>
                              <AlertDialogTrigger asChild>
                                <Button
                                  size="icon"
                                  variant="destructive"
                                  disabled={deletingId === user.id}
                                >
                                  {deletingId === user.id ? (
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                  ) : (
                                    <Trash2 className="h-4 w-4" />
                                  )}
                                </Button>
                              </AlertDialogTrigger>

                              <AlertDialogContent className="border-[#333] bg-[#222]">
                                <AlertDialogHeader>
                                  <AlertDialogTitle className="text-white">
                                    Delete User
                                  </AlertDialogTitle>

                                  <AlertDialogDescription className="text-gray-400">
                                    This action cannot be undone.
                                  </AlertDialogDescription>
                                </AlertDialogHeader>

                                <AlertDialogFooter>
                                  <AlertDialogCancel className="border-[#333] bg-transparent text-white hover:bg-[#333]">
                                    Cancel
                                  </AlertDialogCancel>

                                  <AlertDialogAction
                                    onClick={() => handleDelete(user.id)}
                                    className="bg-red-600 hover:bg-red-700"
                                  >
                                    Delete
                                  </AlertDialogAction>
                                </AlertDialogFooter>
                              </AlertDialogContent>
                            </AlertDialog>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
